<?php
declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/bootstrap.php';
use App\Domain\Client\ClientRepository;use App\Application\Client\ClientLogoUploader;
$repository=new ClientRepository(app_database());$id=(int)($_GET['id']??$_POST['id']??0);$client=$repository->find($id);if(!$client){http_response_code(404);exit('Client introuvable.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{$logo=(new ClientLogoUploader(APP_ROOT.'/photo/clients'))->upload($_FILES['logo_client']??null,$client['logo_client']??null);$repository->update($id,['code'=>trim((string)$_POST['code_client']),'name'=>trim((string)$_POST['nom_client']),'location'=>trim((string)$_POST['localisation_client']),'city'=>trim((string)$_POST['commune_client']),'postal_box'=>trim((string)$_POST['bp_client']),'country'=>trim((string)$_POST['pays_client']),'created_at'=>(string)$_POST['date_creat_client'],'logo'=>$logo]);header('Location: liste_client.php');exit;}catch(Throwable $e){$error=$e->getMessage();}
function ce(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Modifier le client</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"></head><body class="module-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container"><div class="module-heading"><div class="module-heading__copy"><span class="module-heading__icon"><i class="fa-solid fa-building"></i></span><div><h1><?=ce($client['nom_client'])?></h1><p>Mettez à jour son identité visuelle et ses coordonnées.</p></div></div><a href="liste_client.php" class="btn btn-outline-secondary"><i class="fa-solid fa-arrow-left"></i> Retour</a></div><?php if($error):?><div class="alert alert-danger"><?=ce($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card p-4"><input type="hidden" name="id" value="<?=$id?>"><div class="row g-4"><div class="col-lg-4"><label class="form-label">Logo du client</label><?php if($client['logo_client']):?><div class="text-center p-3 mb-2 border rounded"><img src="<?=ce($client['logo_client'])?>" alt="" style="max-width:180px;max-height:110px;object-fit:contain"></div><?php endif;?><input type="file" class="form-control" name="logo_client" accept="image/jpeg,image/png,image/webp,image/svg+xml"></div><div class="col-lg-8"><div class="row g-3"><?php foreach(['code_client'=>'Code client','nom_client'=>'Nom du client','localisation_client'=>'Localisation','commune_client'=>'Commune','bp_client'=>'Boîte postale','pays_client'=>'Pays'] as $name=>$label):?><div class="col-md-6"><label class="form-label"><?=$label?></label><input class="form-control" name="<?=$name?>" value="<?=ce($client[$name])?>" required></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Date de création</label><input type="date" class="form-control" name="date_creat_client" value="<?=ce($client['date_creat_client'])?>" required></div></div></div><div class="col-12 text-end"><button class="btn btn-primary"><i class="fa-solid fa-check me-2"></i>Enregistrer</button></div></div></form></main></body></html>
